package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.nio.charset.Charset;
import java.nio.charset.CharsetEncoder;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class Document_title_TriageGen2Test {









    @Test
    public void testTitle_MultipleTitleTags() {
        Document document = Document.createShell("http://www.example.com");
        Element titleElement1 = document.createElement("title");
        titleElement1.text("Title 1");
        Element titleElement2 = document.createElement("title");
        titleElement2.text("Title 2");
        document.body().appendChild(titleElement1);
        document.body().appendChild(titleElement2);
        document.normalise();
        assertEquals("Title 1", document.title());
    }
}
